#!/usr/bin/env bash
# Correctifs authentification : connexion à durée constante, limite d'essais (10 échecs / 15 min / adresse),
# adresses e-mail en minuscules (+ MIGRATION), lien de réinitialisation consommé atomiquement, HS256 imposé,
# session lue en une requête, store de session simplifié.
# Prérequis : apply-docs-api-trpc.sh. Contient une migration → prisma migrate deploy ensuite.
# Usage (racine du repo) : bash apply-fix-auth.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/lib/auth/password.ts" 2>/dev/null | grep -qF "UNKNOWN_ACCOUNT_HASH"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Quand la donnée change de nature" "apps/web/content/docs/dev/api/pourquoi-trpc.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-api-trpc.sh"; exit 1; }
